import{_ as a,o as s,c as l,a2 as o}from"./chunks/framework.BG8d4IEm.js";const u=JSON.parse('{"title":"vscode 使用指南","description":"","frontmatter":{"tags":["工具","vscode"]},"headers":[],"relativePath":"posts/2018-08-28-vscode.md","filePath":"posts/2018-08-28-vscode.md"}'),n={name:"posts/2018-08-28-vscode.md"};function r(t,e,i,c,d,p){return s(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="vscode-使用指南" tabindex="-1">vscode 使用指南 <a class="header-anchor" href="#vscode-使用指南" aria-label="Permalink to &quot;vscode 使用指南&quot;">​</a></h1><p><strong>vscode 编辑器使用经验</strong></p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>笔者讲解 mac 环境下 vscode 的使用配置。</p><h2 id="界面结构" tabindex="-1">界面结构 <a class="header-anchor" href="#界面结构" aria-label="Permalink to &quot;界面结构&quot;">​</a></h2><p>使用 spotligh 开启 vscode.基本界面显示如下</p><p><img src="https://code.visualstudio.com/assets/docs/getstarted/userinterface/hero.png" alt="" loading="lazy"></p><p>包含如下几块</p><ul><li><strong>Editor</strong> 编辑区,可以横向或纵向打开多个窗口</li><li><strong>Side Bar</strong> 工作时显示对应视图</li><li><strong>Status Bar</strong> 工作状态条</li><li><strong>Activity Bar</strong> 切换视图并显示当前工作文件状态</li><li><strong>Panels</strong> 额外的面板,显示调试\b,终端等信息</li></ul><h2 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h2><h3 id="配置主题" tabindex="-1">配置主题 <a class="header-anchor" href="#配置主题" aria-label="Permalink to &quot;配置主题&quot;">​</a></h3><p><code>⌘K ⌘T</code> 选择 <strong>Monokai Dimmed</strong> 主题</p><p>你可以下载如下插件美化主题:</p><ul><li><a href="https://marketplace.visualstudio.com/items?itemName=Equinusocio.vsc-material-theme" target="_blank" rel="noreferrer">Material Theme</a> 设定主题 <blockquote><p>尤大使用的是 Palenight 主题</p></blockquote></li><li><a href="https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme" target="_blank" rel="noreferrer">Material Icon Theme</a> 主题对应的图标,你也可以选择 <a href="https://marketplace.visualstudio.com/items?itemName=vscode-icons-team.vscode-icons" target="_blank" rel="noreferrer">vscode icon</a></li></ul><h3 id="配置-code-命令" tabindex="-1">配置 code 命令 <a class="header-anchor" href="#配置-code-命令" aria-label="Permalink to &quot;配置 code 命令&quot;">​</a></h3><ol><li><code>⌘⇧p</code> 打开命令行面板</li><li>所有 <code>shell command install</code> 执行此命令</li><li>该命令会在环境变量创建 <code>code</code> 命令行工具</li></ol><p>示例如下:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 打开工程</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#9ECBFF;"> .</span></span>
<span class="line"><span style="color:#6A737D;"># 在最近窗口打开工程</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> -r</span><span style="color:#9ECBFF;"> .</span></span>
<span class="line"><span style="color:#6A737D;"># 创建一个新窗口</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> -n</span><span style="color:#E1E4E8;"> </span></span>
<span class="line"><span style="color:#6A737D;"># \b更换本地语言</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> --local=es</span></span>
<span class="line"><span style="color:#6A737D;"># 比较文件差异</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> -d</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">file</span><span style="color:#F97583;">1&gt;</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">file</span><span style="color:#F97583;">2&gt;</span></span>
<span class="line"><span style="color:#6A737D;"># 打开文件并定向到指定行</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> -g</span><span style="color:#9ECBFF;"> package.json:10:5</span></span>
<span class="line"><span style="color:#6A737D;"># 查看帮助信息</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> --help</span></span>
<span class="line"><span style="color:#6A737D;"># 才 vscode 输出当前命令结果</span></span>
<span class="line"><span style="color:#B392F0;">ls</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> code</span><span style="color:#79B8FF;"> -r</span><span style="color:#9ECBFF;"> -</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 禁用所有插件,并打开当前目录</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> --disable-extensions</span><span style="color:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>更详细的使用参见 <a href="https://code.visualstudio.com/docs/setup/mac#_launching-from-the-command-line" target="_blank" rel="noreferrer">vscode</a></p><h3 id="终端设置" tabindex="-1">终端设置 <a class="header-anchor" href="#终端设置" aria-label="Permalink to &quot;终端设置&quot;">​</a></h3><p>默认 mac 终端下,<code>alt</code> 键无法触发 shell 的多种快捷键, 而是会输出特殊字符.配置如下</p><ol><li><code>⌘,</code> 打开配置</li><li>搜索 <code>terminal.integrated.macOptionIsMeta</code> 设置为 <code>true</code> 即可</li></ol><p>出处参见: <a href="https://github.com/Microsoft/vscode/issues/11314#issuecomment-384067528" target="_blank" rel="noreferrer">https://github.com/Microsoft/vscode/issues/11314#issuecomment-384067528</a></p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><h3 id="面板切换" tabindex="-1">面板切换 <a class="header-anchor" href="#面板切换" aria-label="Permalink to &quot;面板切换&quot;">​</a></h3><ul><li><code>⌘⇧e</code> 文件夹窗口</li><li><code>⌘⇧f</code> 全局搜索</li><li><code>⌘⇧g</code> 版本控制界面</li><li><code>⌘⇧d</code> 调试界面</li><li><code>⌘⇧x</code> 插件界面</li></ul><h3 id="视窗控制" tabindex="-1">视窗控制 <a class="header-anchor" href="#视窗控制" aria-label="Permalink to &quot;视窗控制&quot;">​</a></h3><ul><li><code>⌘b</code> 显示和隐藏 Side Bar</li><li><code>⌘\\</code> 纵向分屏</li><li><code>⌘w</code> 切换窗口</li><li><code>⌘m</code> \b开启 zen 模式编辑文档,\b详见 <a href="https://code.visualstudio.com/docs/getstarted/userinterface#_zen-mode" target="_blank" rel="noreferrer">zen mode</a><blockquote><p>默认快捷键为 <code>⌘k</code> 无法工作,请自行修改</p></blockquote></li><li><code>⌘p</code> 在已添加的目录中\b快速打开文件 <blockquote><p>结合 ? 获取 vscode 支持的相关命令帮助</p></blockquote></li><li><code>⌘p⇧</code> 利用方式运行 vscode 函数</li><li><code>⌃tab</code> 窗口切换,利用 \bshift 方向切换</li></ul><h3 id="导航控制" tabindex="-1">导航控制 <a class="header-anchor" href="#导航控制" aria-label="Permalink to &quot;导航控制&quot;">​</a></h3><ul><li><code>⌘o</code> 打开文件对应的 finder</li><li><code>⌘⇧o</code> 打开文件符号链接列表</li><li><code>⌘t</code> 显示所有打开文件符号链接列表</li><li><code>⌘p</code> 打开文件列表</li><li><code>⌘g</code> 定向到特定行</li><li><code>f12</code> 显示引用的位置</li><li><code>⇧f12</code> 显示所有引用的位置</li></ul><h3 id="光标操作" tabindex="-1">光标操作 <a class="header-anchor" href="#光标操作" aria-label="Permalink to &quot;光标操作&quot;">​</a></h3><ul><li><code>⌥→</code> 单词后</li><li><code>⌥←</code> 单词前</li><li><code>⌘→,⌃e</code> 行尾</li><li><code>⌘←,⌃a</code> 行头</li><li><code>⌘↑</code> 开头</li><li><code>⌘↓</code> 结尾</li><li><code>⌘⇧\\</code> 代码块开头,结尾来回触发</li><li><code>⌘[</code> 向前缩进</li><li><code>⌘]</code> 向后缩进</li><li><code>⌘u</code> 向后跳转光标位置 <blockquote><p>注意该操作不能跨文件执行</p></blockquote></li><li><code>⌃-</code> 向前切换光标位置 <blockquote><p>该操作可以跨文件执行</p></blockquote></li><li><code>⌃⇧-</code> 向前移动光标位置</li></ul><h3 id="其他快捷键" tabindex="-1">其他快捷键 <a class="header-anchor" href="#其他快捷键" aria-label="Permalink to &quot;其他快捷键&quot;">​</a></h3><ul><li><code>f2</code> 选择变量名或者函数名,按该快捷键会重构所有使用该函数或变量的命名</li><li><code>⌘⌥[</code> 折叠片段</li><li><code>⌘⌥]</code> 展开片段</li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>vscode 配置分为如下几种</p><ul><li><code>User Settings</code> 用户配置,全局作用范围</li><li><code>Workspace Settings</code> 作用于当前工程</li><li><code>\bDirectory</code> Settings\` 作用于当前目录 \b详细的配置参见 <a href="https://code.visualstudio.com/docs/getstarted/settings#_default-settings" target="_blank" rel="noreferrer">config</a></li><li><code>files.exclude</code> 配置 sidebar 忽略显示的文件和目录,参见 \b<a href="https://code.visualstudio.com/docs/getstarted/userinterface#_explorer" target="_blank" rel="noreferrer">Explorer tips</a></li><li><code>terminal.integrated.shell.osx</code> 设定 mac 使用的 shell 建议配置为 <code>zsh</code></li></ul><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><h3 id="node-调试" tabindex="-1"><a href="https://code.visualstudio.com/docs/nodejs/nodejs-tutorial" target="_blank" rel="noreferrer">node 调试</a> <a class="header-anchor" href="#node-调试" aria-label="Permalink to &quot;[node 调试](https://code.visualstudio.com/docs/nodejs/nodejs-tutorial)&quot;">​</a></h3><h3 id="更改语言高亮" tabindex="-1">更改语言高亮 <a class="header-anchor" href="#更改语言高亮" aria-label="Permalink to &quot;更改语言高亮&quot;">​</a></h3><ol><li>使用 <code>⌘K M</code> 打开语言面板,选择对应语言.</li></ol><h3 id="更换主题" tabindex="-1">更换主题 <a class="header-anchor" href="#更换主题" aria-label="Permalink to &quot;更换主题&quot;">​</a></h3><ol><li>使用 <code>⌘K ⌘T</code> 打开主题面板</li><li>选择对应主题</li></ol><h3 id="安装扩展" tabindex="-1">安装扩展 <a class="header-anchor" href="#安装扩展" aria-label="Permalink to &quot;安装扩展&quot;">​</a></h3><ol><li>使用 <code>⇧⌘X</code> 打开扩展</li><li>查找并安装扩展</li></ol><h3 id="开发自定义扩展ld" tabindex="-1">开发自定义扩展ld <a class="header-anchor" href="#开发自定义扩展ld" aria-label="Permalink to &quot;开发自定义扩展ld&quot;">​</a></h3><p>详见 <a href="https://code.visualstudio.com/docs/getstarted/tips-and-tricks#_creating-my-own-extension" target="_blank" rel="noreferrer">扩展开发</a> \b</p><h3 id="代码片段" tabindex="-1">代码片段 <a class="header-anchor" href="#代码片段" aria-label="Permalink to &quot;代码片段&quot;">​</a></h3><p><code>⌘⇧p</code> 搜索 <code>config snippets</code> 设置代码片段,使用详见 <a href="https://github.com/liwei0526vip/vscode/blob/master/10%20!%20%E6%8B%92%E7%BB%9D%E9%87%8D%E5%A4%8D%EF%BC%8C%E4%BD%A0%E7%9A%84%E4%BB%A3%E7%A0%81%E7%99%BE%E5%AE%9D%E7%AE%B1%EF%BC%9A%E5%A6%82%E4%BD%95%E4%B9%A6%E5%86%99code%20snippet%EF%BC%9F.md" target="_blank" rel="noreferrer">代码片段</a></p><h3 id="设置识别-npmrc-文件" tabindex="-1">设置识别 npmrc 文件 <a class="header-anchor" href="#设置识别-npmrc-文件" aria-label="Permalink to &quot;设置识别 npmrc 文件&quot;">​</a></h3><p>由于 npmrc 格式和 ini 文件类似,采用如下方式识别 npmrc 文件</p><ol><li><code>⌘,</code> 打开配置</li><li>搜索 <code>associations</code></li><li>添加如下配置<div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#9ECBFF;">&quot;files.associations&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">	&quot;.npmrc&quot;</span><span style="color:#E1E4E8;">:</span><span style="color:#9ECBFF;">&quot;ini&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li></ol><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><h3 id="live-server" tabindex="-1">live server <a class="header-anchor" href="#live-server" aria-label="Permalink to &quot;live server&quot;">​</a></h3><p>使用 live server 实现修改实时同步到浏览器。</p><ul><li><code>⌘l⌘o</code> 在浏览器打开 live server</li></ul><h2 id="bugs" tabindex="-1">bugs <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;bugs&quot;">​</a></h2><h3 id="在输入中英文时-有时会出现不显示的-0x08-非法字符" tabindex="-1">在输入中英文时,有时会出现不显示的 0x08 非法字符 <a class="header-anchor" href="#在输入中英文时-有时会出现不显示的-0x08-非法字符" aria-label="Permalink to &quot;在输入中英文时,有时会出现不显示的 0x08 非法字符&quot;">​</a></h3><p>详见 <a href="https://segmentfault.com/a/1190000013357949?utm_source=tag-newest" target="_blank" rel="noreferrer">vscode控制字符引起的问题以及解决思路</a>.参考上述博文配置 <code>&quot;editor.renderControlCharacters&quot;: true</code> 配置后特殊字符会显示为<small style="font-weight:900;">bs</small>.这样在编辑时即可手动删掉 0x08 等不显示字符</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>[ ] <a href="https://www.npmjs.com/package/vscode-todo-plus" target="_blank" rel="noreferrer">todo 工具的学习</a></li><li><a href="https://code.visualstudio.com/docs" target="_blank" rel="noreferrer">vscode</a></li><li><a href="https://www.vscodecandothat.com/" target="_blank" rel="noreferrer">vscode can do</a></li><li><a href="https://github.com/liwei0526vip/vscode" target="_blank" rel="noreferrer">vscode 编辑器</a></li><li>[ ] 插件推荐 <a href="https://www.jonrcorbin.com/the-best-vs-code-extension-list-for-full-stack-developers/" target="_blank" rel="noreferrer">https://www.jonrcorbin.com/the-best-vs-code-extension-list-for-full-stack-developers/</a></li></ul>`,61)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
